WITH -- short_routes AS ( -- SELECT DISTINCT src_id, dest_id -- FROM lis.short_route_sds -- WHERE cohort = '2026' -- ), -- Deduped Funnel Steps (1 row per session + route) srp_deduped AS ( SELECT DISTINCT s.mri_session_id, s.route_id, s.rb_user_id, s.user_type, s.os, s.channel, s.src_id, s.dest_id, op_id, -- CAST(DATE_TRUNC('day', at_timezone(s.__time, 'Asia/Kolkata')) AS DATE) AS doi date_format(at_timezone(s.__time, 'Asia/Kolkata'), '%Y-%b') AS doi -- CASE WHEN sr.src_id IS NOT NULL THEN 'Short Routes' ELSE 'Long Routes' END AS route_type, -- CASE WHEN __time >= TIMESTAMP '2025-11-30 18:30:00' AND __time < TIMESTAMP '2026-01-06 18:30:00' THEN 'Pre DBS' -- WHEN __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' THEN 'Post DBS' -- ELSE 'Others' END AS time_period FROM "user_interaction"."search_route_details" s -- LEFT JOIN short_routes sr ON s.src_id = sr.src_id AND s.dest_id = sr.dest_id WHERE s.__time >= TIMESTAMP '2025-11-30 18:30:00' AND s.__time < TIMESTAMP '2026-01-31 18:30:00' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') -- AND op_id IN (33000) -- AND group_id > 0 -- AND s.os = 'Android' AND s.country = 'IND' -- GROUP BY 1,2,3,4,5,6,7,8,9 ), sl_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2025-11-30 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), mpax_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2025-11-30 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), tco_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."create_order_details" WHERE __time >= TIMESTAMP '2025-11-30 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2025-11-30 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), addpay_deduped AS ( SELECT mri_session_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."make_payment_details" WHERE __time >= TIMESTAMP '2025-11-30 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1 ), confirm_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2025-11-30 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' -- AND os = 'Android' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) SELECT -- 'MTD Dec 28' AS month_period, srp.doi, UPPER(srp.user_type) as user_type, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, -- srp.route_type, COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT sl.mri_session_id) AS slload, COUNT(DISTINCT pax.mri_session_id) AS paxload, COUNT(DISTINCT tco.mri_session_id) AS tcoload, COUNT(DISTINCT oi.mri_session_id) AS paymentload, COUNT(DISTINCT ap.mri_session_id) AS addPayClick, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, -- COUNT(DISTINCT srp.rb_user_id) AS srpUsers, -- COUNT(DISTINCT sl.rb_user_id) AS slUsers, -- COUNT(DISTINCT pax.rb_user_id) AS paxUsers, -- COUNT(DISTINCT tco.rb_user_id) AS tcoUsers, -- COUNT(DISTINCT oi.rb_user_id) AS orderinfoUsers, -- COUNT(DISTINCT conf.rb_user_id) AS confirmUsers, SUM(conf.tin_count) AS tin FROM srp_deduped srp LEFT JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN mpax_deduped pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN tco_deduped tco ON srp.mri_session_id = tco.mri_session_id AND srp.route_id = tco.route_id LEFT JOIN orderinfo_deduped oi ON srp.mri_session_id = oi.mri_session_id AND srp.route_id = oi.route_id LEFT JOIN addpay_deduped ap ON ap.mri_session_id = oi.mri_session_id LEFT JOIN confirm_deduped conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id GROUP BY 1,2,3 -- ,4,5,6
